use std::{collections::BTreeMap,fs};fn main(){let root="research/hec_residual_span_20261116/affine-promotion";let mut all=BTreeMap::<(u64,u64),(usize,usize,usize,u64,u64)>::new();for l in fs::read_to_string(format!("{root}/CONTROL.tsv")).unwrap().lines().skip(1){let v:Vec<_>=l.split('\t').collect();let n=|j:usize|v[j].parse::<u64>().unwrap();all.insert((n(0),n(1)),(0,0,0,0,0));}let mut seen=std::collections::BTreeSet::new();for l in fs::read_to_string(format!("{root}/CONTROL.stderr")).unwrap().lines().filter(|s|s.starts_with("PROMOTE\t")){let v:Vec<_>=l.split('\t').collect();assert_eq!(v.len(),10);let n=|j:usize|v[j].parse::<u64>().unwrap();assert!(seen.insert((n(1),n(2),n(5))));let e=all.get_mut(&(n(1),n(2))).unwrap();e.0+=1;if v[9]=="false"{e.1+=1;if n(7)!=0{e.2+=1;if e.3==0{e.3=n(3);e.4=n(4);}}}}assert_eq!(all.len(),6);println!("p\tsm\tall_promoted\tpromoted_before_k\tnonzero_target_term_before_k\tfirst_target_term_row\tfirst_target_term_anchor");for((p,sm),(a,b,c,d,e))in all{println!("{p}\t{sm}\t{a}\t{b}\t{c}\t{d}\t{e}")}eprintln!("unique_promotion_events={} all_6_workloads_reported=true",seen.len());}
